//! The Zig file of a component: public declarations and functions, then the
//! private FFI declarations, codecs and callback plumbing.

use std::fmt::Write;

use super::calls::Receiver;
use super::names::{doc, ident};
use super::types::Gen;

impl Gen<'_> {
    pub(crate) fn emit_source(&self) -> String {
        let mut out = String::from(
            "// This file was autogenerated by uniffi-bindgen-zig. Do not edit it by hand.\n",
        );
        if let Some(d) = self.ci.namespace_docstring() {
            out.push_str(&doc(Some(d), 0).replace("///", "//!"));
        }
        out.push_str("\nconst std = @import(\"std\");\nconst uniffi = @import(\"uniffi.zig\");\n");
        for ns in self.external_modules() {
            let _ = writeln!(out, "const {} = @import(\"{ns}.zig\");", ident(&ns));
        }
        out.push('\n');
        out.push_str(&self.emit_declarations());
        for f in self.ci.function_definitions() {
            out.push_str(&doc(f.docstring(), 0));
            out.push_str(&self.callable(f, &self.fn_name(f.name()), &Receiver::None, None, ""));
        }
        out.push_str("// ---- Everything below is used by the bindings only ----\n\n");
        out.push_str(&self.emit_ffi());
        out.push_str(&self.emit_buffers());
        out.push_str(&self.emit_ensure_init());
        out.push_str(&self.emit_codecs());
        out.push_str(&self.emit_callbacks());
        out
    }

    /// The modules of the other components whose types this one uses.
    fn external_modules(&self) -> Vec<String> {
        let mut out: Vec<String> = self
            .all_types()
            .iter()
            .filter_map(|t| self.external_module(t))
            .collect();
        out.sort();
        out.dedup();
        out.retain(|ns| ns != self.ci.namespace());
        out
    }

    fn emit_buffers(&self) -> String {
        let mut out = format!(
            "fn bufferFrom(bytes: []const u8) uniffi.RustBuffer {{\n    var status: uniffi.RustCallStatus = .{{}};\n    const buffer = ffi.{from}(.{{ .len = @intCast(bytes.len), .data = bytes.ptr }}, &status);\n    if (status.code != uniffi.call_success) @panic(\"uniffi: could not allocate a RustBuffer\");\n    return buffer;\n}}\n\nfn bufferFree(buffer: uniffi.RustBuffer) void {{\n    var status: uniffi.RustCallStatus = .{{}};\n    ffi.{free}(buffer, &status);\n}}\n\n",
            from = self.ci.ffi_rustbuffer_from_bytes().name(),
            free = self.ci.ffi_rustbuffer_free().name(),
        );
        if self.has_async_callbacks() {
            out.push_str(
                "fn droppedFuture(handle: u64) callconv(.c) void {\n    _ = handle;\n}\n\n",
            );
        }
        out
    }

    fn has_async_callbacks(&self) -> bool {
        self.ci
            .callback_interface_definitions()
            .iter()
            .any(|cb| cb.methods().iter().any(|m| m.is_async()))
            || self
                .ci
                .object_definitions()
                .iter()
                .any(|o| o.has_callback_interface() && o.methods().iter().any(|m| m.is_async()))
    }

    fn emit_ensure_init(&self) -> String {
        let ns = self.ci.namespace();
        let mut body = String::new();
        // Components this one uses come first.
        for m in self.external_modules() {
            let _ = writeln!(body, "    {}.uniffiEnsureInit();", ident(&m));
        }
        let contract = self.ci.ffi_uniffi_contract_version();
        let _ = writeln!(
            body,
            "    if (ffi.{}() != {}) @panic(\"uniffi: {ns}: contract version mismatch, rebuild the bindings for this library\");",
            contract.name(),
            self.ci.uniffi_contract_version()
        );
        if !self.config.omit_checksums {
            for (name, expected) in self.ci.iter_checksums() {
                let _ = writeln!(
                    body,
                    "    if (ffi.{name}() != {expected}) @panic(\"uniffi: {ns}: API checksum mismatch, rebuild the bindings and the library together\");"
                );
            }
        }
        for cb in self.ci.callback_interface_definitions() {
            let _ = writeln!(body, "    {}Init();", base(cb.name()));
        }
        for obj in self.ci.object_definitions() {
            if obj.has_callback_interface() {
                let _ = writeln!(body, "    {}Init();", base(obj.name()));
            }
        }
        format!(
            "var uniffi_initialized: bool = false;\nvar uniffi_init_mutex: uniffi.Mutex = .{{}};\n\n/// Checks the library matches these bindings and registers the vtables, once.\npub fn uniffiEnsureInit() void {{\n    if (@atomicLoad(bool, &uniffi_initialized, .acquire)) return;\n    uniffi_init_mutex.lock();\n    defer uniffi_init_mutex.unlock();\n    if (uniffi_initialized) return;\n{body}    @atomicStore(bool, &uniffi_initialized, true, .release);\n}}\n\n"
        )
    }
}

/// The prefix of a type's private plumbing: `listener` for `Listener`.
fn base(type_name: &str) -> String {
    super::names::snake(type_name)
        .trim_start_matches("@\"")
        .trim_end_matches('"')
        .to_owned()
}
